static void UAM_Hexa_PD_Obs_QGround_ppval(const real_T pp_breaks[6], const
  real_T pp_coefs[160], real_T x, real_T v[8])
{
  // Start for MATLABSystem: '<S5>/Polynomial Trajectory'
  if (rtIsNaN(x)) {
    for (int32_T low_ip1 = 0; low_ip1 < 8; low_ip1++) {
      v[low_ip1] = (rtNaN);
    }
  } else {
    int32_T high_i;
    int32_T low_ip1;
    int32_T mid_i;
    UAM_Hexa_PD_Obs_QGround_B.low_i = 0;
    low_ip1 = 1;
    high_i = 6;
    while (high_i > low_ip1 + 1) {
      mid_i = ((UAM_Hexa_PD_Obs_QGround_B.low_i + high_i) + 1) >> 1;
      if (x >= pp_breaks[mid_i - 1]) {
        UAM_Hexa_PD_Obs_QGround_B.low_i = mid_i - 1;
        low_ip1 = mid_i;
      } else {
        high_i = mid_i;
      }
    }

    low_ip1 = UAM_Hexa_PD_Obs_QGround_B.low_i << 3;
    UAM_Hexa_PD_Obs_QGround_B.xloc = x -
      pp_breaks[UAM_Hexa_PD_Obs_QGround_B.low_i];
    memcpy(&v[0], &pp_coefs[low_ip1], sizeof(real_T) << 3U);
    for (UAM_Hexa_PD_Obs_QGround_B.low_i = 0; UAM_Hexa_PD_Obs_QGround_B.low_i <
         3; UAM_Hexa_PD_Obs_QGround_B.low_i++) {
      high_i = ((UAM_Hexa_PD_Obs_QGround_B.low_i + 1) * 40 + low_ip1) - 1;
      for (mid_i = 0; mid_i < 8; mid_i++) {
        v[mid_i] = pp_coefs[(high_i + mid_i) + 1] +
          UAM_Hexa_PD_Obs_QGround_B.xloc * v[mid_i];
      }
    }
  }

  // End of Start for MATLABSystem: '<S5>/Polynomial Trajectory'
}

real_T rt_atan2d_snf(real_T u0, real_T u1)
{
  real_T y;
  if (rtIsNaN(u0) || rtIsNaN(u1)) {
    y = (rtNaN);
  } else if (rtIsInf(u0) && rtIsInf(u1)) {
    int32_T tmp;
    int32_T tmp_0;
    if (u0 > 0.0) {
      tmp = 1;
    } else {
      tmp = -1;
    }

    if (u1 > 0.0) {
      tmp_0 = 1;
    } else {
      tmp_0 = -1;
    }

    y = atan2(static_cast<real_T>(tmp), static_cast<real_T>(tmp_0));
  } else if (u1 == 0.0) {
    if (u0 > 0.0) {
      y = RT_PI / 2.0;
    } else if (u0 < 0.0) {
      y = -(RT_PI / 2.0);
    } else {
      y = 0.0;
    }
  } else {
    y = atan2(u0, u1);
  }

  return y;
}

